    "<button class=\"md\" id=\"rep\" data-a=\"Repeat\" aria-label=\"Repeat\" aria-pressed=\"false\"><svg class=\"i\"><use href=\"#rp\"/></svg></button>\n"
    "</div>\n"
    "<div class=\"vol\"><svg class=\"i\"><use href=\"#vl\"/></svg><input type=\"range\" id=\"vol\" min=\"0\" max=\"100\" step=\"1\" value=\"0\" data-a=\"Volume\" aria-label=\"Volume\"><svg class=\"i\"><use href=\"#vh\"/></svg><span id=\"voln\">0</span></div>\n"
    "</section>\n"
    "<section class=\"card hint\" id=\"hint\"><img src=\"/icon-192.png\" alt=\"\"><div><b data-t=\"Keep it on your home screen\">Keep it on your home screen</b><p id=\"how\"></p></div><button id=\"hintx\" data-t=\"Done\">Done</button></section>\n"
    "<section><h2 data-t=\"Up next\">Up next</h2><div class=\"card list\" id=\"queue\"><div class=\"empty\" data-t=\"Nothing up next\">Nothing up next</div></div></section>\n"
    "<section><h2 data-t=\"Search\">Search</h2>\n"
    "<div class=\"q\"><svg><use href=\"#sr\"/></svg><input type=\"search\" id=\"q\" data-p=\"Songs, artists, albums\" placeholder=\"Songs, artists, albums\" autocomplete=\"off\" enterkeyhint=\"search\"></div>\n"
    "<div class=\"card list\" id=\"res\" hidden></div></section>\n"
    "<section><h2 data-t=\"Software update\">Software update</h2><div class=\"card up\"><p id=\"upl\" dir=\"auto\"></p><div class=\"ub\" id=\"ubw\" hidden><i id=\"ub\"></i></div>\n"
    "<button class=\"ghost\" id=\"upb\" data-t=\"Send an update file\">Send an update file</button><input type=\"file\" id=\"upf\" accept=\".gbupdate\" hidden></div></section>\n"
    "<section class=\"foot\"><button class=\"ghost\" id=\"shotb\" data-t=\"Take screenshot\">Take screenshot</button><a id=\"shotlink\" download><img id=\"shot\" alt=\"\"></a></section>\n"
    "</main>\n"
    "<div id=\"toast\" role=\"status\"></div>\n"
    "<script>\n"
    "\"use strict\";\n"
    "var $=function(i){return document.getElementById(i)},W={},N={},cfg=0,qrev=-1,cov=-1,S=-1,wantShot=0,base=0,at=0,len=0,playing=false,\n"
    "seeking=false,volDrag=0,volT=0,fails=0,pollT=0,lastQ=0,star=false;\n"
    "function t(s){return W[s]||s}\n"
    "function words(){document.querySelectorAll(\"[data-t]\").forEach(function(e){if(e.id!=\"title\"||!N.title)e.textContent=t(e.dataset.t)});\n"
    "document.querySelectorAll(\"[data-a]\").forEach(function(e){e.setAttribute(\"aria-label\",t(e.dataset.a))});\n"
    "document.querySelectorAll(\"[data-p]\").forEach(function(e){e.placeholder=t(e.dataset.p)});\n"
    "$(\"how\").textContent=t(/iP(hone|ad|od)/.test(navigator.userAgent)||navigator.maxTouchPoints>1&&/Mac/.test(navigator.userAgent)?\n"
    "\"Tap Share, then Add to Home Screen.\":\"Open the browser menu, then Add to Home screen.\")}\n"
    "function mm(ms){var s=Math.max(0,Math.floor(ms/1000)),m=Math.floor(s/60);return m+\":\"+(\"0\"+s%60).slice(-2)}\n"
    "function get(u){return fetch(u,{cache:\"no-store\"}).then(function(r){if(r.status==401){pairOn();throw 401}if(!r.ok)throw r.status;return r.json()})}\n"
    "var paired=1;\n"
    "function pairOn(){if(!paired)return;paired=0;document.body.classList.add(\"lock\");$(\"pair\").hidden=false;$(\"pc\").value=\"\";$(\"pe\").textContent=\"\";ask()}\n"
    "function ask(){fetch(\"/pair\",{cache:\"no-store\"}).then(function(r){if(r.status==429)$(\"pe\").textContent=t(\"Too many tries. Wait a minute, then try again.\")}).catch(function(){})}\n"
    "function online(ok){fails=ok?0:fails+1;document.body.classList.toggle(\"off\",fails>1);if(fails>1&&playing){base+=performance.now()-at;at=performance.now();playing=false}}\n"
    "function toast(s){var e=$(\"toast\");e.textContent=s;e.classList.add(\"on\");clearTimeout(e._t);e._t=setTimeout(function(){e.classList.remove(\"on\")},1600)}\n"
    "function buzz(){if(navigator.vibrate)navigator.vibrate(8)}\n"
    "function use(b,id){b.querySelector(\"use\").setAttribute(\"href\",\"#\"+id)}\n"
    "function fill(r){var mx=+r.max||1;r.style.setProperty(\"--p\",(100*Math.min(1,(+r.value)/mx))+\"%\")}\n"
    "function hello(){return get(\"/api/hello\").then(function(h){W=h.w;cfg=h.cfg;star=h.star;document.documentElement.lang=h.lang;document.documentElement.dir=h.dir;\n"
    "var d=matchMedia(\"(prefers-color-scheme: light)\").matches,s=document.documentElement.style;\n"
    "s.setProperty(\"--acc\",d?h.acc.l:h.acc.d);s.setProperty(\"--acct\",d?h.acc.lt:h.acc.dt);s.setProperty(\"--ink\",d?h.acc.li:h.acc.di);\n"
    "HA=h.acc;words();show(N,1)})}\n"
    "var HA=null;\n"
    "matchMedia(\"(prefers-color-scheme: light)\").addEventListener&&matchMedia(\"(prefers-color-scheme: light)\").addEventListener(\"change\",function(){cfg=0;hello()});\n"
    "function show(n,again){if(!n||n.title===undefined)return;\n"
    "var sent=n._t||performance.now();N=n;\n"
    "if(n.cfg!=cfg&&!again){cfg=n.cfg;hello()}\n"
    "if(S<0)S=n.shot;else if(n.shot!=S){S=n.shot;if(wantShot){var u=\"/shot.png?\"+S;$(\"shot\").src=u;$(\"shot\").style.display=\"block\";$(\"shotlink\").href=u;wantShot=0}}\n"
    "$(\"title\").textContent=n.title||t(\"Nothing playing\");$(\"artist\").textContent=n.artist||\"\xc2""\xa0""\";$(\"album\").textContent=n.album||\"\xc2""\xa0""\";\n"
    "document.title=n.title?n.title+\" \xc2""\xb7"" GabagoolOS\":\"GabagoolOS Remote\";\n"
    "len=n.len;playing=n.playing;\n"
    "var p=n.pos+(n.playing?Math.min(400,(performance.now()-sent)/2):0),guess=base+(playing?performance.now()-at:0);\n"
    "if(!playing||Math.abs(guess-p)>350||again){base=p;at=performance.now()}\n"
    "$(\"seek\").max=Math.max(1,len);$(\"len\").textContent=mm(len);$(\"seek\").disabled=!len;\n"
    "var pp=$(\"pp\");use(pp,n.playing?\"pa\":\"pl\");pp.setAttribute(\"aria-label\",t(n.playing?\"Pause\":\"Play\"));\n"
    "var lv=$(\"love\");lv.classList.toggle(\"on\",n.loved);lv.setAttribute(\"aria-pressed\",n.loved);use(lv,star?(n.loved?\"st\":\"so\"):(n.loved?\"ht\":\"ho\"));\n"
    "lv.disabled=!n.title;$(\"prev\").disabled=$(\"next\").disabled=!n.title;\n"
    "$(\"shuf\").classList.toggle(\"on\",n.shuffle);$(\"shuf\").setAttribute(\"aria-pressed\",n.shuffle);\n"
    "var rp=$(\"rep\");rp.classList.toggle(\"on\",n.repeat>0);rp.setAttribute(\"aria-pressed\",n.repeat>0);use(rp,n.repeat==2?\"r1\":\"rp\");\n"
    "rp.setAttribute(\"aria-label\",t(n.repeat==2?\"Repeat one\":\"Repeat\"));\n"
    "if(!volDrag&&performance.now()-volT>1200){$(\"vol\").value=n.vol;fill($(\"vol\"));$(\"voln\").textContent=n.vol}\n"
    "if(n.cover!=cov){cov=n.cover;var im=$(\"art\");im.classList.remove(\"on\");if(cov){im.onload=function(){im.classList.add(\"on\")};im.onerror=function(){im.classList.remove(\"on\")};im.src=\"/cover?k=\"+cov}else im.removeAttribute(\"src\")}\n"
    "if(n.qrev!=qrev||performance.now()-lastQ>20000)queue();\n"
    "tick()}\n"
    "function stamp(p){var t0=performance.now();return p.then(function(n){n._t=t0;online(1);show(n);return n})}\n"
    "function now(){clearTimeout(pollT);return stamp(get(\"/api/now\")).catch(function(e){online(e==401)}).then(function(){if(!document.hidden)pollT=setTimeout(now,fails?2500:1000)})}\n"
    "function cmd(c){buzz();return stamp(get(\"/api/cmd?c=\"+c)).catch(function(){online(0)})}\n"
    "function tick(){if(!seeking){var p=Math.min(len,base+(playing?performance.now()-at:0)),s=$(\"seek\");s.value=p;fill(s);var x=mm(p);if($(\"pos\").textContent!=x)$(\"pos\").textContent=x}}\n"
    "(function raf(){if(playing&&!document.hidden)tick();requestAnimationFrame(raf)})();\n"
    "$(\"pp\").onclick=function(){playing=!playing;use($(\"pp\"),playing?\"pa\":\"pl\");base=base+(playing?0:performance.now()-at);at=performance.now();cmd(\"toggle\")};\n"
    "$(\"prev\").onclick=function(){cmd(\"prev\")};$(\"next\").onclick=function(){cmd(\"next\")};\n"
    "$(\"shuf\").onclick=function(){cmd(\"shuffle\")};$(\"rep\").onclick=function(){cmd(\"repeat\")};\n"
    "$(\"love\").onclick=function(){cmd(\"love\")};\n"
    "var sk=$(\"seek\");\n"
    "sk.addEventListener(\"input\",function(){seeking=true;fill(sk);$(\"pos\").textContent=mm(+sk.value)});\n"
    "sk.addEventListener(\"change\",function(){var v=Math.round(+sk.value);base=v;at=performance.now();seeking=false;buzz();stamp(get(\"/api/seek?ms=\"+v)).catch(function(){})});\n"
    "var vo=$(\"vol\");\n"
    "vo.addEventListener(\"input\",function(){fill(vo);$(\"voln\").textContent=vo.value;volT=performance.now();if(!volDrag)volDrag=setTimeout(function(){volDrag=0;get(\"/api/vol?v=\"+vo.value).catch(function(){})},120)});\n"
    "vo.addEventListener(\"change\",function(){clearTimeout(volDrag);volDrag=0;volT=performance.now();get(\"/api/vol?v=\"+vo.value).catch(function(){})});\n"
    "function row(title,artist,extra){var r=document.createElement(\"div\");r.className=\"row\";var d=document.createElement(\"div\"),a=document.createElement(\"div\"),b=document.createElement(\"div\");\n"
    "d.dir=\"auto\";a.className=\"rt\";a.textContent=title;b.className=\"ra\";b.textContent=artist||\"\xc2""\xa0""\";d.append(a,b);r.append(d);if(extra)extra.forEach(function(x){r.append(x)});return r}\n"
    "function ib(icon,label,fn){var b=document.createElement(\"button\");b.className=\"ib\";b.setAttribute(\"aria-label\",t(label));b.innerHTML='<svg class=\"i\"><use href=\"#'+icon+'\"/></svg>';\n"
    "b.onclick=function(e){e.stopPropagation();fn()};return b}\n"
    "function queue(){lastQ=performance.now();get(\"/api/queue\").then(function(q){qrev=q.rev;var box=$(\"queue\");box.textContent=\"\";\n"
    "if(!q.items.length){var e=document.createElement(\"div\");e.className=\"empty\";e.textContent=t(\"Nothing up next\");box.append(e);return}\n"
    "q.items.forEach(function(it){var x=[];if(it.q){var c=document.createElement(\"span\");c.className=\"chip\";c.textContent=t(\"Queued\");x.push(c)}\n"
    "var r=row(it.title,it.artist,x);r.onclick=function(){buzz();stamp(get(\"/api/jump?k=\"+it.k+\"&r=\"+q.rev)).catch(function(){})};box.append(r)});\n"
    "if(q.more){var m=document.createElement(\"div\");m.className=\"more\";m.textContent=\"+\"+q.more;box.append(m)}}).catch(function(){})}\n"
    "var ST=0;\n"
    "$(\"q\").addEventListener(\"input\",function(){clearTimeout(ST);ST=setTimeout(find,220)});\n"
    "function find(){var q=$(\"q\").value.trim(),box=$(\"res\");if(!q){box.hidden=true;box.textContent=\"\";return}\n"
    "get(\"/api/search?q=\"+encodeURIComponent(q)).then(function(r){if($(\"q\").value.trim()!=q)return;box.hidden=false;box.textContent=\"\";\n"
    "if(!r.songs.length){var e=document.createElement(\"div\");e.className=\"empty\";e.textContent=t(\"Nothing found\");box.append(e);return}\n"
    "r.songs.forEach(function(s){var go=function(m,msg){buzz();stamp(get(\"/api/play?t=\"+s.t+\"&m=\"+m)).then(function(){if(msg)toast(t(msg))}).catch(function(){})};\n"
    "var el=row(s.title,[s.artist,s.album].filter(Boolean).join(\" \xc2""\xb7"" \"),[ib(\"pn\",\"Play next\",function(){go(\"next\",\"Playing next\")}),ib(\"ad\",\"Add to queue\",function(){go(\"queue\",\"Added to queue\")})]);\n"
    "el.onclick=function(){go(\"now\")};box.append(el)})}).catch(function(){})}\n"
    "$(\"shotb\").onclick=function(){wantShot=1;cmd(\"shot\")};\n"
    "var standalone=matchMedia(\"(display-mode: standalone)\").matches||navigator.standalone;\n"
    "try{if(!standalone&&!localStorage.getItem(\"hint\"))$(\"hint\").classList.add(\"on\")}catch(e){}\n"
    "$(\"hintx\").onclick=function(){$(\"hint\").classList.remove(\"on\");try{localStorage.setItem(\"hint\",\"1\")}catch(e){}};\n"
    "document.addEventListener(\"visibilitychange\",function(){if(!document.hidden)now()});\n"
    "function upd(){get(\"/api/update\").then(function(u){$(\"upl\").textContent=u.line;$(\"upb\").disabled=!u.key||u.busy;clearTimeout(upd.t);if(u.busy)upd.t=setTimeout(upd,1000)}).catch(function(){})}\n"
    "$(\"upb\").onclick=function(){$(\"upf\").click()};\n"
    "$(\"upf\").onchange=function(){var f=$(\"upf\").files[0];if(!f)return;var x=new XMLHttpRequest();$(\"ubw\").hidden=false;$(\"upb\").disabled=true;\n"
    "x.upload.onprogress=function(e){if(e.lengthComputable)$(\"ub\").style.width=(100*e.loaded/e.total)+\"%\"};\n"
    "x.onloadend=function(){$(\"ubw\").hidden=true;$(\"ub\").style.width=\"0\";$(\"upf\").value=\"\";upd()};\n"
    "x.open(\"POST\",\"/update\");x.send(f);setTimeout(upd,400)};\n"
    "$(\"pf\").onsubmit=function(e){e.preventDefault();var c=$(\"pc\").value.trim();if(!c)return;\n"
    "fetch(\"/pair?code=\"+encodeURIComponent(c),{cache:\"no-store\"}).then(function(r){\n"
    "if(r.ok){paired=1;document.body.classList.remove(\"lock\");$(\"pair\").hidden=true;hello().catch(function(){});now();upd();queue();return}\n"
    "$(\"pc\").value=\"\";$(\"pe\").textContent=t(r.status==429?\"Too many tries. Wait a minute, then try again.\":r.status==410?\"That code ran out. Type the new one.\":\"That code is not right.\");\n"
    "if(r.status==410)ask()}).catch(function(){})};\n"
    "words();hello().catch(function(){});now();upd();\n"
    "</script></body></html>\n";
#endif
